// FUNCTION: BFME2 0x000AA73A size=120 name=?getNameAndIndex@@YAPBDABVAsciiString@@PAH_N@Z evidence=N:ledger
const char *getNameAndIndex(const AsciiString &path, Int *index, Bool fullPath)
{
	// "...\\name12.ext": the frame number is the run of digits before the last
	// '.', and the name is either the whole path or what follows the last '\\'.
	const char *afterSlash = path.reverseFind('\\');
	if (afterSlash == NULL)
		return NULL;

	const char *number = path.reverseFind('.');
	if (number == NULL)
		return NULL;
	while (isdigit(number[-1]))
		--number;
	sscanf(number, "%d.", index);

	if (fullPath)
		return path.str();
	return afterSlash + 1;
}

